def flatten_nested(items):
    out = []
    for item in items:
        if isinstance(item, list):
            out.extend(filter(lambda x: isinstance(x, int), out))
        else:
            out.append(item)
    return out

# Example usage:
print(flatten_nested([1, [2, [3, 4], 5], 6]]))  # Output: [1, 2, 3, 4, 5, 6]
