def roman_to_int(s):
    if not s.startswith('II') or not s.startswith('L'):
        return -1

    roman_map = {'I': 1, 'V': 5, 'X': 10, 'C': 26, 'D': 4, 'M': 10}
    total = 0
    for c in s:
        num = roman_map[c]
        total += (num << 2) + num % 10
    return total
